css:
.chapter-scope {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #d9531e;
  --warm: #f4f4f4;
  --line: #e0e0e0;
  --paper: #ffffff;

  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  line-height: 1.6;
  font-size: 16px;
  max-width: 1200px;
  margin: 0 auto;
}

.scope-header h2 {
  font-size: 2rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
  border-bottom: 2px solid var(--accent);
  display: inline-block;
  padding-bottom: 0.25rem;
}

.lead {
  font-size: 1.1rem;
  color: var(--muted);
  margin-bottom: 2rem;
  max-width: 800px;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
}

.narrative-col article {
  margin-bottom: 2rem;
}

.narrative-col h3 {
  font-size: 1.25rem;
  margin-top: 0;
  color: var(--ink);
}

.source-block {
  background: var(--warm);
  padding: 1rem;
  border-left: 4px solid var(--muted);
  margin-top: 1rem;
  font-size: 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.btn-source {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.25rem 0.5rem;
  font-size: 0.8rem;
  cursor: pointer;
  align-self: flex-start;
  font-family: inherit;
}

.btn-source:hover {
  border-color: var(--ink);
  color: var(--ink);
}

.panel-interactive {
  background: var(--warm);
  padding: 1.5rem;
  border-radius: 4px;
  border: 1px solid var(--line);
}

.panel-interactive h4 {
  margin-top: 0;
  font-size: 1.1rem;
}

.panel-desc {
  font-size: 0.9rem;
  color: var(--muted);
  margin-bottom: 1.5rem;
}

.control-group {
  margin-bottom: 1.5rem;
}

.control-group label {
  display: block;
  font-weight: bold;
  margin-bottom: 0.5rem;
  font-size: 0.9rem;
}

.control-group select {
  width: 100%;
  padding: 0.5rem;
  font-size: 1rem;
  border: 1px solid var(--line);
  background: var(--paper);
  color: var(--ink);
}

.viz-container {
  background: var(--paper);
  border: 1px solid var(--line);
  padding: 1rem;
  margin-bottom: 1rem;
  min-height: 220px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
}

.unit-label {
  font-size: 0.75rem;
  color: var(--muted);
  text-align: right;
  margin-top: 0.25rem;
}

.legend {
  display: flex;
  gap: 1rem;
  font-size: 0.85rem;
  margin-top: 0.5rem;
  justify-content: center;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.data-readout {
  display: flex;
  justify-content: space-between;
  border-top: 1px solid var(--line);
  padding-top: 1rem;
  margin-top: 1rem;
}

.metric {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.metric .label {
  font-size: 0.8rem;
  color: var(--muted);
}

.metric .value {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--ink);
}

.metric .status-ok {
  color: #2e7d32;
}

.btn-reset {
  width: 100%;
  padding: 0.75rem;
  background: var(--ink);
  color: var(--paper);
  border: none;
  font-size: 0.9rem;
  cursor: pointer;
  margin-top: 1rem;
  transition: opacity 0.2s;
}

.btn-reset:hover {
  opacity: 0.9;
}

.scope-footer {
  margin-top: 3rem;
  border-top: 1px solid var(--line);
  padding-top: 1.5rem;
}

.limitations-box h5 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.limitations-box ul {
  margin: 0;
  padding-left: 1.25rem;
  font-size: 0.9rem;
  color: var(--muted);
}
button[data-source]{background:#fff!important;color:#265976!important}
