(function() {
  'use strict';

  // Data derived strictly from S027 text descriptions
  // Values represent the DIFFERENCE (Delta) in percentage points relative to the reference group.
  // Reference group is implicitly set to 0 for visualization of the delta.
  const DATA = {
    gender: {
      dim: "保护女性 (Sparing Females)",
      // Text: "male respondents are 0.06 percentage point less inclined to spare females... compared to female respondents"
      groups: [
        { name: "女性 (Female, 基准)", val: 0.00, color: "var(--ink)" }, 
        { name: "男性 (Male)", val: -0.06, color: "var(--accent)" }  // 0.06 less inclined
      ],
      delta: 0.06,
      unit: "percentage points"
    },
    religiosity: {
      dim: "保护人类 (Sparing Humans)",
      // Text: "one increase in standard deviation of religiosity... associated with 0.09 more inclination to spare humans"
      groups: [
        { name: "低宗教性 (基准)", val: 0.00, color: "var(--ink)" },
        { name: "高宗教性 (+1SD)", val: 0.09, color: "var(--accent)" } // 0.09 more inclined
      ],
      delta: 0.09,
      unit: "inclination units"
    }
  };

  const selectEl = document.getElementById('demographic-select');
  const svgEl = document.getElementById('diff-chart');
  const deltaValEl = document.getElementById('delta-val');
  const resetBtn = document.getElementById('reset-filter');

  function renderChart(key) {
    const data = DATA[key];
    if (!data) return;

    // Clear SVG
    svgEl.innerHTML = '';

    // Update Text with data-value attribute for verification
    deltaValEl.textContent = Math.abs(data.delta).toFixed(2);
    deltaValEl.setAttribute('data-value', Math.abs(data.delta).toFixed(2));

    // Chart Dimensions
    const width = 500;
    const height = 220;
    const barHeight = 40;
    const gap = 40;
    const centerX = 250; // Zero line in the middle
    const scale = 2000; // Scale factor to make small decimals visible (1.0 = 2000px)

    // Create Zero Line
    const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
    line.setAttribute("x1", centerX);
    line.setAttribute("y1", 30);
    line.setAttribute("x2", centerX);
    line.setAttribute("y2", 180);
    line.setAttribute("stroke", "var(--line)");
    line.setAttribute("stroke-dasharray", "4 4");
    svgEl.appendChild(line);

    const zeroLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
    zeroLabel.setAttribute("x", centerX);
    zeroLabel.setAttribute("y", 25);
    zeroLabel.setAttribute("text-anchor", "middle");
    zeroLabel.setAttribute("font-size", "12px");
    zeroLabel.setAttribute("fill", "var(--muted)");
    zeroLabel.textContent = "基准 (0.00)";
    svgEl.appendChild(zeroLabel);

    // Create Bars
    data.groups.forEach((group, index) => {
      const y = 50 + index * (barHeight + gap);
      const barWidth = Math.abs(group.val) * scale;
      const x = group.val < 0 ? (centerX - barWidth) : centerX;

      // Bar Rect
      const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
      rect.setAttribute("x", x);
      rect.setAttribute("y", y);
      rect.setAttribute("width", barWidth === 0 ? 1 : barWidth); // Ensure visible line for 0
      rect.setAttribute("height", barHeight);
      rect.setAttribute("fill", group.val === 0 ? "var(--ink)" : "var(--accent)");
      rect.setAttribute("rx", 4);
      svgEl.appendChild(rect);

      // Label (Left side)
      const text = document.createElementNS("http://www.w3.org/2000/svg", "text");
      text.setAttribute("x", centerX - 15);
      text.setAttribute("y", y + barHeight / 2 + 5);
      text.setAttribute("text-anchor", "end");
      text.setAttribute("font-size", "14px");
      text.setAttribute("fill", "var(--ink)");
      text.textContent = group.name;
      svgEl.appendChild(text);

      // Value Label (Right side of bar)
      const valText = document.createElementNS("http://www.w3.org/2000/svg", "text");
      const valX = group.val < 0 ? (x - 5) : (x + barWidth + 5);
      const valAnchor = group.val < 0 ? "end" : "start";
      valText.setAttribute("x", valX);
      valText.setAttribute("y", y + barHeight / 2 + 5);
      valText.setAttribute("text-anchor", valAnchor);
      valText.setAttribute("font-size", "14px");
      valText.setAttribute("fill", "var(--muted)");
      valText.setAttribute("font-weight", "bold");
      const sign = group.val > 0 ? "+" : "";
      valText.textContent = sign + group.val.toFixed(2);
      svgEl.appendChild(valText);
    });

    // Axis Label
    const axisLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
    axisLabel.setAttribute("x", width / 2);
    axisLabel.setAttribute("y", 210);
    axisLabel.setAttribute("text-anchor", "middle");
    axisLabel.setAttribute("font-size", "12px");
    axisLabel.setAttribute("fill", "var(--muted)");
    axisLabel.textContent = "相对偏好差异 (Relative Preference Difference)";
    svgEl.appendChild(axisLabel);
  }

  function handleInput(e) {
    renderChart(e.target.value);
  }

  function handleReset() {
    selectEl.value = "gender";
    renderChart("gender");
  }

  // Init
  if(selectEl && svgEl && deltaValEl && resetBtn) {
    selectEl.addEventListener('change', handleInput);
    resetBtn.addEventListener('click', handleReset);
    renderChart('gender');
  }

})();
